// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    uint256 constant FUND = 1 ether;

    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), FUND);
    }

    function testFuzz_property(address receiver, uint96 amount) public {
        vm.assume(receiver.code.length == 0); // plain recipient, transfer succeeds
        amount = uint96(bound(uint256(amount), 2, FUND)); // amount != 1 and affordable

        uint256 before = receiver.balance;
        c.sendTo(receiver, amount);

        assertTrue(receiver.balance - before == amount);
    }
}
